    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Removable orthoses have proven their value in the recovery process of other fractures of the long bones, and are increasingly suggested as an alternative to a cast for stable type B fractures [16, 17]. Orthoses can be taken off, allowing early (weight-bearing) mobilization, potentially preventing the consequences of rigid immobilization and accelerating recovery [16, 18].",
      "reason": "For an intervention-effect review, the retrieved evidence describes a hypothesised mechanism: removable orthoses enable early mobilization, may prevent consequences of rigid immobilization, and can accelerate recovery."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not report a logic model or any diagrammatic logic model showing hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 62
